def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if isinstance(value, timedelta):
        return value.total_seconds()
    elif isinstance(value, int):
        return timedelta(seconds=value)
    else:
        raise ValueError("Invalid value type provided to dehydrate_timedelta")

def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values."""
    if value.days != 0:
        return "%d:%d:%d:%d" % (value.days, value.seconds // 3600, (value.seconds // 60) % 60, value.seconds % 60)
    else:
        return "%d:%s" % (value.seconds // 60, value.seconds)

