def unit_of_work(func):
    def wrapper(*args, **kwargs):
        metadata = kwargs.pop('metadata', None)
        timeout = kwargs.pop('timeout', None)

        try:
            tx = dbms.get_neo4j_transaction(metadata=metadata, timeout=timeout)
            result = func(*args, **kwargs, tx=tx)
            tx.commit()
            return result
        except (TimeoutException, DatabaseError) as e:
            if tx:
                tx.rollback()
            raise e
        finally:
            if tx:
                tx.close()

    return wrapper

