def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """

    # Check if n and qid are valid
    if n <= 0 and qid < 0:
        raise ValueError("At least one of n and qid must be specified.")

    # If dehydration_hooks or hydration_hooks are not None, validate the types
    if dehydration_hooks or hydration_hooks:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict.")
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict.")
        for key, value in dehydration_hooks.items():
            if not isinstance(key, type):
                raise TypeError("dehydration_hooks keys must be types.")
            if not callable(value):
                raise TypeError("dehydration_hooks values must be callable.")
        for key, value in hydration_hooks.items():
            if not isinstance(key, type):
                raise TypeError("hydration_hooks keys must be types.")
            if not callable(value):
                raise TypeError("hydration_hooks values must be callable.")

    # If handlers are not empty, validate their types
    if handlers:
        if not isinstance(handlers, dict):
            raise TypeError("handlers must be a dict.")
        for key, value in handlers.items():
            if not isinstance(key, str):
                raise TypeError("handler keywords must be strings.")
            if not callable(value):
                raise TypeError("handler values must be callable.")

    # Create the DISCARD message
    message = {"type": "DISCARD", "qid": qid, "n": n}

    # If dehydration_hooks are provided, dehydrate the message
    if dehydration_hooks:
        message = dehydrate(message, dehydration_hooks)

    # Add the message to the output queue
    self.output_queue.append(message)

    # If hydration_hooks are provided, hydrate the message
    if hydration_hooks:
        message = hydrate(message, hydration_hooks)

    # If handlers are provided, return a Response object with the handlers
    if handlers:
        return Response(message, handlers)
    else:
        return None

def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object """
    if dehydration_hooks:
        for value_type, dehydrate_function in dehydration_hooks.items():
            if value_type not in self.hooks.dehydration:
                self.hooks.dehydration[value_type] = dehydrate_function
            else:
                raise ValueError(f"Type {value_type} is already registered with {self.hooks.dehydration[value_type].__name__}")
    if hydration_hooks:
        for value_type, hydrate_function in hydration_hooks.items():
            if value_type not in self.hooks.hydration:
                self.hooks.hydration[value_type] = hydrate_function
            else:
                raise ValueError(f"Type {value_type} is already registered with {self.hooks.hydration[value_type].__name__}")
    handler = _PackstreamRequester(
        {
            "method": "DISCARD",
            "params": {"n": n, "queryId": qid},
            "handlers": handlers,
        },
        self.address,
    )
    self.output_queue.append(handler)
    return Response(handler)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
    # Check if the mode is valid
    if mode != "READ" and mode != "WRITE":
        raise ValueError("Invalid mode argument: {}".format(mode))

    # Check if the database name is specified
    if db:
        # Check if the Bolt version is 4.0 or higher
        if self.version < "4.0":
            raise ValueError("DB name is only supported in Bolt 4.0+")

    # Check if the imp_user is specified
    if imp_user:
        # Check if the Bolt version is 4.4 or higher
        if self.version < "4.4":
            raise ValueError("Impersonation is only supported in Bolt 4.4+")

    # Check if the dehydration and hydration hooks are specified
    if dehydration_hooks and hydration_hooks:
        # Check if the Bolt version is 4.6 or higher
        if self.version < "4.6":
            raise ValueError("Hooks are only supported in Bolt 4.6+")

    # Check if the handlers are specified
    if not handlers:
        raise ValueError("At least one handler must be specified")

    # Create the BEGIN message
    message = {"type": "BEGIN", "mode": mode, "bookmarks": bookmarks, "metadata": metadata,
               "timeout": timeout, "db": db, "imp_user": imp_user,
               "dehydration_hooks": dehydration_hooks, "hydration_hooks": hydration_hooks,
               "handlers": handlers}

    # Add the message to the output queue
    self.queue.put(message)

    # Return a Response object
    return self.Response()

