def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    shuffled = []
    for i in range(len(seq)):
        index = i
        while index in shuffled:
            index = (index + 1) % len(seq)
        shuffled.append(seq[index])
    return shuffled

