        return wrapper

    return decorator

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    try:
        file_obj = open(file_name, "ab+" if overwrite else "a+")
        try:
            bytes_written = file_obj.write(text_buffer.encode(encoding))
        finally:
            file_obj.close()
    except Exception as e:
        raise IOError(f"Failed to write to file '{file_name}': '{str(e)}'")
    return bytes_written

