        return len(text_buffer)

def file_to_textbuffer(file_name, encoding):
    if not os.path.isfile(file_name) or not os.access(file_name, os.R_OK):
        raise ValueError("file {} does not exist or cannot be read".format(file_name))
    if not encoding:
        encoding = "utf-8"
    try:
        with open(file_name, "rb") as f:
            return f.read().decode(encoding)
    except UnicodeDecodeError as e:
        raise ValueError("invalid encoding specified: {}".format(e))

