def to_csv(self: Annotation, separator: str = ",", header: str = None):
    """Convert graph's points to CSV."""
    delimiter = separator
    headerString = header

    # Get the annotations for the current element
    annotations = self.annotations(predicate=None, name=None, id=None, qtype=self.type, qrelation=self.relation, qvalue=self.value, merged=False)
    if len(annotations) == 0:
        return []

    # Build the CSV headers
    headers = ["x", "y"]
    if headerString is not None:
        headers = [headerString] + headers

    # Convert the annotations to CSV rows
    rows = []
    for annotation in annotations:
        row = [annotation.x, annotation.y]
        if annotation.is_empty():
            row.append("")
        else:
            row.append(annotation.text)
        rows.append(row)

    # Return the CSV data as a string
    return "\n".join([delimiter.join(headers), "\n".join([delimiter.join(row) for row in rows])])

