def integral(bins, edges):
    bin_widths = edges[1:] - edges[:-1]
    return sum([bin_value * bin_width for bin_value, bin_width in zip(bins, bin_widths)])

def integral(bins, edges):
    if len(bins) != len(edges) - 1:
        raise ValueError("Number of bins must be equal to number of edges minus 1")
    result = 0
    for i in range(len(bins)):
        result += bins[i] * (edges[i + 1] - edges[i])
    return result

