def difference(d1, d2, level=-1):
    result = {}
    for key, value in d1.items():
        if key not in d2:
            result[key] = value
        elif level == -1:
            result[key] = value
        elif isinstance(value, dict):
            result[key] = difference(value, d2[key], level-1)
        else:
            result[key] = value
    return result

def difference(d1, d2, level=-1) -> dict:
    def __helper(d1: dict, d2: dict, level: int) -> dict:
        result = {}

        for key in d1:
            if (key not in d2) or ((key in d2) and (d1[key] != d2[key]) and level > 1):
                if (level == -1) or (d1[key] != d2[key] and level > 1):
                    result[key] = d1[key]
                elif level == 0:
                    result[key] = d1[key]
                else:
                    result[key] = __helper(d1[key], d2[key], level-1)

        return result

    return __helper(d1, d2, level)

def difference(d1, d2, level=-1):
    if level == -1:
        level = sys.maxsize
    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dictionary")
    if not isinstance(d2, dict):
        raise TypeError("d2 must be a dictionary")
    if not (isinstance(level, int) and level >= -1):
        raise ValueError("level must be an integer >= -1")
    d = {}
    for k, v in d1.items():
        if k not in d2 or v != d2[k]:
            d[k] = v
            if isinstance(v, dict) and level > 0:
                d[k] = difference(d1[k], d2.get(k, {}), level - 1)
                if d[k] == {} or not isinstance(d[k], dict):
                    del d[k]
    return d

def difference(d1, d2, level=-1):
    if level == -1 or level >= json.dumps(d1).count('{'):
        return {k: v for k, v in d1.items() if k not in d2}
    return {k: v for k, v in d1.items() if k not in d2 and json.dumps(v).count('{') <= level + 1 and k not in difference(d2, v, level - 1)}

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if len(coord) != len(self.bins):
        raise ValueError("The coordinate must be the same length as the histogram's bins.")

    for i in range(len(coord)):
        if self.bins[i] is None:
            self.bins[i] = [0] * len(self.bins[i])

        if weight is not None:
            self.bins[i][coord[i]] += weight
        else:
            self.bins[i][coord[i]] += 1

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if self.edges is None:
        raise ValueError("Histogram has no edges")

    try:
        idx = self.edges.index(coord)
    except ValueError:
        return

    self.counts[idx] += weight

    return self

