def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Recursively updates a partial ``last_applied_manifest`` from a partial Kubernetes response
    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    """
    if not last_applied_manifest:
        last_applied_manifest = []
    if not response:
        return last_applied_manifest
    if not observer_schema:
        return last_applied_manifest
    #retrieve list of existing keys from last_applied_manifest
    existing_keys = set(el.pop("key") for el in last_applied_manifest)
    new_keys = set(el.pop("key") for el in response)
    missing_keys = new_keys - existing_keys
    for key in missing_keys:
        if key in response:
            last_applied_manifest.append({"key": key}
    for el in last_applied_manifest:
        if el.pop("key") in response:
            el.update(update_last_applied_manifest_dict_from_resp(el, observer_schema["manifest"], response[key]))
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    if 'observed' in observer_schema:
        observed = observer_schema['observed']
        if isinstance(observed, str):
            last_applied_manifest[observed] = response[observed]
        elif isinstance(observed, list):
            for field in observed:
                update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
    else:
        raise KeyError('observed field is not present in the Kubernetes response')

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, value in observer_schema.items():
        if field not in response:
