def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """

    resources = []
    for name, resource in app.spec.manifest.items():
        if resource.get("metadata", {}).get("rbac"):
            continue  # Skip this resource, it has an RBAC annotation

        schema = {
            "type": "object",
            "properties": {},
            "required": [],
        }

        for field in resource["metadata"].items():
            if field.name not in ["name", "namespace"]:
                schema["properties"][field.name] = {"type": "string"}
                schema["required"].append(field.name)

        for field in resource["spec"].items():
            if field.name not in ["name", "namespace"]:
                schema["properties"][field.name] = {"type": "string"}
                schema["required"].append(field.name)

        # Store the default schema in the application manifest
        app.spec.manifest[name]["metadata"]["attributes"]["observer_schema"] = schema

    return resources

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    observer_schema = {}
    for resource_name in app.spec.manifest:
        resource = app.spec.manifest[resource_name]
        if resource.kind not in observer_schema:
            observer_schema[resource.kind] = {}
        observer_schema[resource.kind][resource_name] = {}
        for field in resource.spec:
            if isinstance(field, JsonnetType) and field.kind == 'field':
                if field.get('type') == JsonnetType('object'):
                    observer_schema[resource.kind][resource_name][field.name] = JsonnetType(
                        'object', name=field.name, kind='field', spec=field.spec
                    )
                elif field.get('type') == JsonnetType('string'):
                    observer_schema[resource.kind][resource_name][field.name] = JsonnetType(
                        'string', name=field.name, kind='field', spec=field.spec
                    )
                elif field.get('type') == JsonnetType('number'):
                    observer_schema[resource.kind][resource_name][field.name] = JsonnetType(
                        'number', name=field.name, kind='field', spec=field.spec
                    )
                else:
                    observer_schema[resource.kind][resource_name][field.name] = JsonnetType(
                        field.type, name=field.name, kind='field', spec=field.spec
                    )
    return observer_schema

def generate_default_observer_schema(app):
    for resource in app.spec.manifest.resources:
        if not resource.observer_schema:
            resource.observer_schema = ObserverSchema(app, resource, None, resource.kind)
            for field in resource.fields:
                if field.is_child_field:
                    continue
                field_schema = ObserverSchemaField(field.name, field.dtype)
                field_schema.values = [field.value]
                field_schema.default = field.value
                resource.observer_schema.add_field(field_schema)
    return app

def format(self, sql, params):
    if isinstance(sql, (str, bytes)):
        sql = sql.replace(":", "%s")
        if isinstance(params, dict):
            params = [params[key] for key in sorted(params)]
        else:
            params = list(params)
        return sql % params
    else:
        raise ValueError("sql must be a string or bytes")

def format(self, sql, params):
    if isinstance(params, Mapping):
        formatted_params = OrderedDict((f":{k}", params[k]) for k in sorted(params.keys(), key=int))
    else:
        formatted_params = [f":{i+1}" for i in range(len(params))]
    return (sql.format(*formatted_params), OrderedDict((f":{k}", params[k]) for k in sorted(params.keys(), key=int)))

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:

        if isinstance(sql, (str, bytes)):
            params = list(params) if isinstance(params, dict) else params
            formatted_sql = self.get_format_sql(sql, params)
            out_params = self.get_out_params(params, sql)
            return formatted_sql, out_params
        else:
            raise TypeError("sql must be a str or bytes")


    def get_format_sql(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> AnyStr:
        param_style = self.sql_params.in_style if isinstance(params, dict) else self.sql_params.in_style.format(len(params))
        return sql.replace(param_style, '?')


    def get_out_params(self, params: Union[Dict[Union[str, int], Any], Sequence[Any]], sql: AnyStr) -> Union[Dict[Union[str, int], Any], Sequence[Any]]:
        param_style = self.sql_params.in_style if isinstance(params, dict) else self.sql_params.in_style.format(len(params))
        param_tag = re.search(f'{re.escape(param_style)}(.*)', sql)
        if not param_tag:
            return params
        else:
            out_params = {}
            for param in params:
                out_params[param_tag.group(1)] = param
            return out_params

def format_many(self, sql, many_params):
    # Convert the SQL query to use out-style parameters
    sql = sql.format(*many_params)

    # Convert each set of in-style parameters to out-style parameters
    out_params = []
    for params in many_params:
        if isinstance(params, Mapping):
            out_params.append(params)
        elif isinstance(params, Sequence):
            out_params.append(dict(enumerate(params)))
        else:
            raise ValueError("params must be a Mapping or Sequence")

    return sql, out_params

