    # Check if the SQL query is a string or bytes
    if not isinstance(sql, (str, bytes)):
        raise TypeError("The 'sql' argument must be a string or bytes")

    # Check if the 'many_params' is an iterable
    if not isinstance(many_params, collections.abc.Iterable):
        raise TypeError("The 'many_params' argument must be an iterable")

    # Check if each set of params is a mapping or a sequence
    for params in many_params:
        if not isinstance(params, (collections.abc.Mapping, collections.abc.Sequence)):
            raise TypeError("The params argument must be a mapping or a sequence")

    # Format the SQL query with the out-style parameters
    out_sql = self._format_sql(sql)

    # Convert each set of in-style parameters to out-style parameters
    out_params = []
    for params in many_params:
        if isinstance(params, collections.abc.Mapping):
            # If the params is a mapping, convert it to a list
            mapping = params
            out_params.append(list(mapping.values()))
        else:
            # If the params is a sequence, leave it as is
            out_params.append(params)

    return out_sql, out_params

