def check_digests_present_and_used(self, manifest_files, digests_used):
    for manifest_file in manifest_files:
        assert isinstance(manifest_file, str), "Invalid manifest file type: " + type(manifest_file)
        assert os.path.exists(manifest_file), "Manifest file does not exist: " + manifest_file
        with open(manifest_file) as f:
            digests = json.loads(f.read())["digests"]
        assert digests, "Manifest file does not contain any digests: " + manifest_file
        for digest in digests:
            assert digest in digests_used, "Digest not used: " + digest

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for file in manifest_files:
        if not file.digest or file.digest not in digests_used:
            # If the file is missing a digest or the digest is not marked as used, raise an error
            raise ValueError("Missing or unused digest for file: " + file.name)
    for digest in digests_used:
        # Check that each used digest is actually present in the manifest files
        if not any(file.digest == digest for file in manifest_files):
            raise ValueError("Used digest not found: " + digest)
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""

        # Check that each digest in the manifest is present and used
        for digest in manifest_files:
            # Check that the digest is present in the manifest
            if digest not in manifest_files:
                raise DigestNotInManifestError(f"Digest {digest} is not present in the manifest")

            # Check that the digest is used in the manifest
            if digest not in digests_used:
                raise DigestNotUsedError(f"Digest {digest} is not used in the manifest")

        # Check that each digest in digests_used is present in the manifest
        for digest in digests_used:
            if digest not in manifest_files:
                raise DigestNotInManifestError(f"Digest {digest} in digests_used is not present in the manifest")

        # No errors were raised, all digests are present and used
        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        if not manifest_files or not digests_used:
            raise Exception("Manifest files and set of digests used must be provided as input.")
        digests_used.update(manifest_files)
        if len(digests_used) > len(manifest_files):
            raise Exception("There are missing digests in the manifest.")
        for digest in digests_used:
            if digest not in manifest_files:
                raise Exception(f"{digest} is missing from the manifest.")
        return digests_used

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        # Parse the manifest file to retrieve the digests
        with open(manifest_file, "r") as f:
            digests = []
            for line in f:
                if line.startswith("Digest"):
                    digest = line.split(",")[1]
                    digests.append(digest)
        # Check that all digests needed are present
        for digest in digests:
            if digest not in digests_used:
                raise ValueError(f"{digest} is not present in the model")
        # Check that all digests used are present
        for digest in digests_used:
            if digest not in digests:
                raise ValueError(f"{digest} is not used in the model")

def validate_as_prior_version(prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("The input variable prior should be an InventoryValidator object")

    if self.id != prior.id:
        raise ValueError("The input inventory object has a different ID than the current inventory")

    if not all([self.columns[i].dtype == prior.columns[i].dtype for i in range(len(self.columns))]):
        raise ValueError("The input inventory object has a different column datatype than the current inventory")

    if not all([self.columns[i].data == prior.columns[i].data for i in range(len(self.columns))]):
        raise ValueError("The input inventory object has different data than the current inventory")

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")
    if not self.compare_identifiers(prior):
        raise ValueError("inventories are not comparable")
    if not self.compare_sequences(prior):
        raise ValueError("inventories have different sequences")
    if not self.compare_versions(prior):
        raise ValueError("inventories have different versions")

def validate_as_prior_version(self, prior):
    assert isinstance(prior, InventoryValidator)
    assert self.docLabel == prior.docLabel
    assert self.version > prior.version
    for vp in self.vocabularies:
        if vp.name not in prior.vocabularies:
            raise InvalidPriorVersionError('Vocabulary "{}" is not in the prior version.'.format(vp.name))
        assert len(vp.items) == len(prior.vocabularies[vp.name].items)
        for vpi, _ in enumerate(vp.items):
            if vp.items[vpi].id != prior.vocabularies[vp.name].items[vpi].id:
                raise InvalidPriorVersionError('Vocabulary "{}" has a different item ID (indexed by "{}") in the prior version.'.format(vp.name, vp.items[vpi].id))
        for vpi, _ in enumerate(vp.items):
            if vp.items[vpi].typ != prior.vocabularies[vp.name].items[vpi].typ:
                raise InvalidPriorVersionError('Vocabulary "{}" has a different item type (indexed by "{}") in the prior version.'.format(vp.name, vp.items[vpi].id))
    for sp in self.spans:
        if sp.name not in prior.spans:
            raise InvalidPriorVersionError('Span "{}" is not in the prior version.'.format(sp.name))
        assert len(sp.annotations) == len(prior.spans[sp.name].annotations)
        for sa, _ in enumerate(sp.annotations):
            if sp.annotations[sa].id != prior.spans[sp.name].annotations[sa].id:
                raise InvalidPriorVersionError('Span "{}" has a different annotation ID (indexed by "{}") in the prior version.'.format(sp.name,  sp.annotations[sa].id))

