def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Generate mapping of logical paths to files
    logical_path_to_files = {}
    for element in inventory:
        for content_file in element.get_content_files(version):
            if (content_file.logical_path, content_file.version) not in logical_path_to_files:
                logical_path_to_files[(content_file.logical_path, content_file.version)] = set()
            logical_path_to_files[(content_file.logical_path, content_file.version)].add(content_file)

    # Filter out duplicate files
    logical_path_to_unique_files = {}
    for logical_path, files in logical_path_to_files.items():
        unique_files = []
        for file in files:
            if file not in unique_files:
                unique_files.append(file)
        logical_path_to_unique_files[logical_path] = unique_files

    return logical_path_to_unique_files

