def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check if the fixity block is a dict
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block should be a dict")

    # Check if the fixity block has the required fields
    if "total" not in fixity:
        raise ValueError("Fixity block should have a 'total' field")

    if "errors" not in fixity:
        raise ValueError("Fixity block should have an 'errors' field")

    if "items" not in fixity:
        raise ValueError("Fixity block should have an 'items' field")

    # Check if the items field is a list
    if not isinstance(fixity["items"], list):
        raise TypeError("Fixity items should be a list")

    # Check if the items field has the required fields
    for item in fixity["items"]:
        if "file" not in item:
            raise ValueError("Fixity item should have a 'file' field")

        if "fixed" not in item:
            raise ValueError("Fixity item should have a 'fixed' field")

    # Check that all referenced files are present in the manifest
    for item in fixity["items"]:
        if item["file"] not in manifest_files:
            raise ValueError("File {} is not present in the manifest".format(item["file"]))

    return fixity

def validate_fixity(self, fixity, manifest_files):
    # Check that the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise TypeError("Parameter 'fixity' must be a dictionary.")

    # Check that the required fields are present and are of the correct type
    required_fields = ["version", "file_list"]
    for field in required_fields:
        if field not in fixity or not isinstance(fixity[field], str):
            raise ValueError("Fixity block is missing required field '{}'".format(field))

    # Check that the version field is a valid version identifier
    version = fixity["version"]
    if not version.startswith("urn:ipid"):
        raise ValueError("Invalid version identifier in fixity block.")

    # Check that the file_list field is a list
    file_list = fixity["file_list"]
    if not isinstance(file_list, list):
        raise TypeError("Field 'file_list' in fixity block must be a list.")

    # Check that all files listed in the fixity block are also present in the manifest
    for file in file_list:
        if file not in manifest_files:
            raise ValueError("File '{}' is not present in the manifest.".format(file))

    # If we got this far, the fixity block is valid
    return True

def validate_fixity(self, fixity, manifest_files):
    if not isinstance(fixity, dict) or "files" not in fixity or "algorithms" not in fixity or "date" not in fixity:
        raise ValueError("Invalid fixity block in inventory.")
    if not isinstance(manifest_files, list):
        raise ValueError("Invalid manifest files in inventory.")
    for f in fixity["files"]:
        if f not in manifest_files:
            raise ValueError("File in fixity block not found in manifest files.")
    return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Check if fixity is a dictionary
        if not isinstance(fixity, dict):
            raise ValueError("Fixity must be a dictionary.")
        # Check if fixity has the required keys
        required_keys = ["algorithm", "hash"]
        for key in required_keys:
            if key not in fixity:
                raise ValueError(f"The fixity block is missing the required key '{key}'.")
        # Check if the algorithm is in the allowed list
        if fixity["algorithm"] not in ["md5", "sha1", "sha256", "sha512"]:
            raise ValueError(f"The algorithm '{fixity['algorithm']}' is not allowed.")
        # Check if the hash is a string
        if not isinstance(fixity["hash"], str):
            raise ValueError("The hash must be a string.")
        # Check if each file in the manifest is referenced in the fixity block
        for file in manifest_files:
            if file["url"] not in fixity:
                raise ValueError(f"The file '{file['url']}' is not referenced in the fixity block.")
            # Check if the fixity for each file is a dictionary
            if not isinstance(fixity[file["url"]], dict):
                raise ValueError(f"The fixity for the file '{file['url']}' must be a dictionary.")
            # Check if the fixity for each file has the required keys
            required_keys = ["algorithm", "hash"]
            for key in required_keys:
                if key not in fixity[file["url"]]:
                    raise ValueError(f"The fixity for the file '{file['url']}' is missing the required key '{key}'.")
            # Check if the algorithm is in the allowed list
            if fixity[file["url"]]["algorithm"] not in ["md5", "sha1", "sha256", "sha512"]:
                raise ValueError(f"The algorithm '{fixity[file['url']]['algorithm']}' is not allowed for the file '{file['url']}'.")
            # Check if the hash is a string
            if not isinstance(fixity[file["url"]]["hash"], str):
                raise ValueError(f"The hash for the file '{file['url']}' must be a string.")
        # If the validation is successful, return True
        return True

def validate_fixity(self, fixity, manifest_files):
        if fixity is None or len(fixity) == 0:
            raise InvalidInventoryError("No fixity block found in inventory")

        fixity_list = self.fixity_to_list(fixity)
        if len(fixity_list) != len(manifest_files):
            raise InvalidInventoryError("Number of files listed in fixity block does not match number of files in manifest")

        for file in manifest_files:
            if file not in fixity_list:
                raise InvalidInventoryError("Unknown file referenced in fixity block: " + file)

        for file in fixity_list:
            if file not in manifest_files:
                raise InvalidInventoryError("File listed in fixity block is not in manifest: " + file)

        # Make sure the fixity value for each file is a non-empty string
        for file, fixity_value in fixity_list.items():
            if not isinstance(fixity_value, str) or len(fixity_value.strip()) == 0:
                raise InvalidInventoryError("Fixity value for file " + file + " is not a valid string")

        return True

