    packages = {}
    for file in os.listdir(folder):
        if os.path.isfile(file) and file.endswith(".xml"):
            basename = os.path.basename(file)
            if basename not in packages:
                packages[basename] = []
            packages[basename].append(file)
    return packages

def _explore_folder(folder):
    files = os.listdir(folder)
    packages = {}
    for file in files:
        # parse xml file
        package_name, _ = os.path.splitext(file)
        try:
            tree = ET.parse(os.path.join(folder, package_name))
            root = tree.getroot()
            # get package name
            package_name = root.attrib["name"]
            if package_name not in packages:
                packages[package_name] = []
            # get configuration from xml file
            configuration = root.find("configuration")
            if configuration is not None:
                for child in configuration:
                    if child.tag == "plugin":
                        packages[package_name].append(child.attrib["package"])
        except (ET.ParseError, OSError) as e:
            # skip if file is not an xml file or cannot be read
            continue
    return packages

def _explore_folder(folder):
    import os
    import xml.etree.ElementTree as ET

    basename_dict = {}

    for filename in os.listdir(folder):
        if filename.endswith(".xml"):
            tree = ET.parse(os.path.join(folder, filename))
            root = tree.getroot()
            basename_dict[root.get("id")] = root.text

    return basename_dict

