    """
    Convert all texts with the pattern `w:st="` to `w-st="`
    """
    fixed_content = ''
    for word in content.split():
        if word.startswith('w:st="') and not word.startswith('w-st="'):
            fixed_word = f'w-st="{word[4:]}'
            fixed_content += fixed_word + " "
        else:
            fixed_content += word + " "
    return fixed_content.strip()

