def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    new_args = []
    for arg in args:
        if arg.is_binary_operator('&'):
            lhs, rhs = arg.left, arg.right
            if lhs.equals(rhs):
                new_args.append(lhs)
                continue
            elif lhs.equals(rhs.invert()):
                new_args.append(lhs)
                continue
            elif rhs.is_binary_operator('|'):
                rhs_lhs, rhs_rhs = rhs.left, rhs.right
                if rhs_lhs.equals(rhs_rhs):
                    new_args.append(lhs & rhs_lhs)
                    continue
                elif rhs_lhs.is_binary_operator('&'):
                    rhs_lhs_lhs, rhs_lhs_rhs = rhs_lhs.left, rhs_lhs.right
                    if rhs_lhs_lhs.equals(rhs_lhs_rhs):
                        new_args.append(lhs & rhs_lhs_lhs)
                        continue
                elif rhs_rhs.is_binary_operator('&'):
                    rhs_rhs_lhs, rhs_rhs_rhs = rhs_rhs.left, rhs_rhs.right
                    if rhs_rhs_lhs.equals(rhs_rhs_rhs):
                        new_args.append(lhs & rhs_rhs_lhs)
                        continue
        elif arg.is_binary_operator('|'):
            lhs, rhs = arg.left, arg.right
            if lhs.equals(rhs):
                new_args.append(lhs)
                continue
            elif lhs.equals(rhs.invert()):
                new_args.append(lhs)
                continue
            elif lhs.is_binary_operator('&'):
                lhs_lhs, lhs_rhs = lhs.left, lhs.right
                if lhs_lhs.equals(lhs_rhs):
                    new_args.append(lhs_lhs | rhs)
                    continue
                elif lhs_lhs.is_binary_operator('&'):
                    lhs_lhs_lhs, lhs_lhs_rhs = lhs_lhs.left, lhs_lhs.right
                    if lhs_lhs_lhs.equals(lhs_lhs_rhs):
                        new_args.append(lhs_lhs_lhs | rhs)
                        continue
                elif lhs_rhs.is_binary_operator('&'):
                    lhs_rhs_lhs, lhs_rhs_rhs = lhs_rhs.left, lhs_rhs.right
                    if lhs_rhs_lhs.equals(lhs_rhs_rhs):
                        new_args.append(lhs_rhs_lhs | rhs)
                        continue
        new_args.append(arg)

def absorb(self, args):
    new_args = []
    for arg in args:
        if arg.operator:
            var1, var2 = arg.variables
            if arg.operator == "&" and var1 == var2:
                new_args.append(var1)
            elif arg.operator == "|" and var1 == var2:
                new_args.append(var1)
            elif arg.operator == "&" and var1 == ~var2:
                new_args.append(var1 & var2)
            elif arg.operator == "|" and var1 == ~var2:
                new_args.append(var1 | var2)
            else:
                new_args.append(arg)
    return new_args

