def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands or not args:
        return

    if isinstance(commands, str):
        commands = [commands]

    if isinstance(args, str):
        args = [args]

    for command in commands:
        result = subprocess.call([command, *args], cwd=cwd, stdout=PIPE, stderr=PIPE if hide_stderr else None, env=env)
        if result.returncode != 0:
            raise RuntimeError("Failed to run command: " + command)

        if verbose:
            print(result.stdout.decode().strip())

def run_command(*commands, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not commands:
        raise ValueError("At least one command is required")

    for command in commands:
        if isinstance(command, str):
            process = subprocess.Popen(command, cwd=cwd, shell=True,
                                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        elif isinstance(command, list):
            process = subprocess.Popen(command, cwd=cwd, shell=False,
                                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        out, err = process.communicate()
        if verbose:
            print(out.strip())
        if hide_stderr:
            print(err.strip())
        if env:
            envionment.update(env)
        process.wait()

