    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version.isdigit():
        raise ValueError("Invalid version identifier: {}".format(version))
    vnum = int(version)
    if vnum >= 1000:
        return str(vnum + 1)
    else:
        return "0{}".format(str(vnum + 1).zfill(3))

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if "." not in version:
        return str(int(version) + 1)
    else:
        major, minor = version.split(".")
        minor = str(int(minor) + 1)
        if minor.startswith("0"):
            minor = minor[1:]
        return major + "." + minor

def next_version(version):
    if not version:
        return "1.0.0.0"
    # Split version into components
    major, minor, bugfix, build = version.split(".")
    # Increment the last component and replace 0's and 1's with 1's
    build = str(int(build) + 1).replace("0", "1")
    # Concatenate components and return
    return ".".join([major, minor, bugfix, build])

