def find_path_type(path):
    path_type = None
    if os.path.isdir(path):
        contents = os.listdir(path)
        if "0=*" in contents:
            path_type = "object"
        elif contents == ["0.NAMASTE.txt", "0=I-D", "0=O-D", "0=A-D"]:
            path_type = "root"
        else:
            for content in contents:
                if content.startswith("0="):
                    if content.endswith((".txt", ".bin")):
                        path_type = "file"
                    else:
                        path_type = "other"
    else:
        path_type = "other"
    return path_type

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """

    if not path.endswith("/"):
        path += "/"

    try:
        with open(path + "0=*", "r") as f:
            lines = f.readlines()
            if len(lines) == 1 and lines[0].startswith("INVENTORY "):
                return "inventory"
            elif len(lines) == 2 and lines[0].startswith("FOLLOWING_INVENTORY "):
                return "object"
            else:
                return "root"
    except FileNotFoundError:
        return "error: no 0=* file found in directory"
    except IsADirectoryError:
        return "error: path is a directory, not a file"

