def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    result = []
    for node in nodes:
        key, value = node
        if not result or result[-1][0] != key:
            result.append(node)
        else:
            if value.tag == 'tag:yaml.org,2002:map':
                result[-1][1].value += value.value
            elif result[-1][1] != value:
                result[-1][1] = value
    return result

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    node_map = {}
    for node in nodes:
        key = node[0]
        value = node[1]
        if not isinstance(key, ScalarNode):
            raise ValueError("The first value of each tuple must be a ScalarNode")
        if not isinstance(value, (MappingNode, ScalarNode, str)):
            raise ValueError("The second value of each tuple must be a MappingNode, ScalarNode, or string")
        if key.value not in node_map:
            node_map[key.value] = value
        else:
            previous_value = node_map[key.value]
            if not isinstance(previous_value, MappingNode):
                raise ValueError("The value for key " + key.value + " must be a MappingNode to merge")
            if not isinstance(value, MappingNode):
                raise ValueError("The value for key " + key.value + " must be a MappingNode to merge")
            node_map[key.value] = previous_value._merge(value)

    result = []
    for key, value in node_map.items():
        result.append((ScalarNode(tag='tag:yaml.org,2002:str', value=key), value))
    return result

def deep_merge_nodes(nodes):
    result = []
    for node in nodes:
        value = node[1]
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            values = value.value
            for key in values:
                if isinstance(key, ruamel.yaml.nodes.ScalarNode) and key.value in [node.value for node in result]:
                    for node in result:
                        if node.key.value == key.value:
                            node.value.value.extend(value.value)
