    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    ctx = dict()
    ctx['global'] = argparse.Namespace(subparser_name='global')

    # unparsed arguments is a flat list of arguments, even if they were generated from subparsers
    # so we need to find the ones that correspond to commands first
    commands = []
    for arg in unparsed_arguments:
        if not arg.startswith('-'):
            commands.append(arg)

    # add parsed arguments to the global namespace
    for arg in unparsed_arguments:
        if not arg.startswith('-'):
            continue
        if arg.startswith('--'):
            ctx['global'].__dict__[arg[2:]] = True
        else:
            ctx['global'].__dict__[arg[1:]] = True

    # iterate over the commands and create a new namespace for each
    for command in commands:
        ctx[command] = argparse.Namespace(subparser_name=command)
        for arg in unparsed_arguments:
            if not arg.startswith('-'):
                continue
            if arg.startswith('--'):
                ctx[command].__dict__[arg[2:]] = True
            else:
