def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if size.lower().endswith("k"):
        return int(float(size[:-1]) * 1000)
    if size.lower().endswith("m"):
        return int(float(size[:-1]) * 1000000)
    if size.lower().endswith("g"):
        return int(float(size[:-1]) * 1000000000)
    return int(size)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    multipliers = {"B": 1, "K": 10**3, "M": 10**6, "G": 10**9}
    if size.isdigit():
        return int(size)
    else:
        key = size[-1]
        if key in multipliers:
            return int(size[:-1]) * multipliers[key]
        else:
            raise ValueError("Invalid input size")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    size = size.upper()
    if size[-1] in ['K', 'M', 'G']:
        return int(float(size[:-1]) * 1000 ** {'K': 1, 'M': 2, 'G': 3}[size[-1]])
    else:
        return int(size)

