def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.

    Arguments:
        config_filenames (list or tuple): List or tuple of configuration filenames to load.
        overrides (dict): Dictionary containing any overrides to apply.
        resolve_env (bool): Resolve environment variables?
    """
    configs = {}
    errors = []
    for filename in config_filenames:
        try:
            with open(filename, "r") as f:
                config = json.load(f)
            if overrides:
                config = {**overrides, **config}
            if resolve_env:
                config = resolve_config_env(config)
            configs[filename] = config
        except Exception as e:
            errors.append(logging.LogRecord("Error reading configuration file", filename, str(e)))
    return configs, errors

