def protocol_handlers(cls, protocol_version=None):
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("Expected a tuple identifying a specific protocol version (e.g. (3, 5)) or None")

        supported_versions = {(3, 5): cls.ProtocolVersionHandler}

        if protocol_version is None:
            return supported_versions
        elif protocol_version in supported_versions:
            return {protocol_version: supported_versions[protocol_version]}
        else:
            return {}

def protocol_handlers(cls, protocol_version=None):
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be passed in a tuple")
            return {protocol_version: cls.select_version(protocol_version)}
        else:
            return {version: cls.select_version(version)
                    for version in cls.supported_versions}

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if not isinstance(values, Iterable) or all(isinstance(x, str) for x in values):
            raise ValueError("`values` should be an Iterable of strings")

        existing_values = cls._raw_values
        if not existing_values:
            existing_values = []

        new_values = [v for v in values if v not in existing_values]
        existing_values.extend(new_values)

        if len(new_values) > 1:
            return cls(new_values)

        return cls(existing_values)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    seq = _seq_from_iterable(seq, bufsize)
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)
    elif isinstance(seq, AbstractSet):
        return set(seq), type(seq)
    elif isinstance(seq, (str, bytes)):
        return seq, type(seq)
    else:
        raise ValueError("'seq' must be a sequence type, not '{0}'".format(type(seq)))

