        return self._scale
    elif isinstance(other, (int, float)):
        self._scale = other

        for attr in ['_x', '_y', '_z']:
            if hasattr(self, attr):
                setattr(self, attr, getattr(self, attr) * other)

        for error in self._scalable_errors:
            setattr(error, '_error', getattr(error, '_error') * other)
    else:
        raise ValueError("Invalid argument for scaling. Must be numeric")

