def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """

    if other is None:
        return self.scale
    elif isinstance(other, (int, float)):
        if self.scale == 0:
            raise LenaValueError("Cannot rescale a graph with unknown scale.")
        self.scale = other
        for field in self.fields:
            if isinstance(self[field], list):
                for error in self[field]:
                    error.rescale(self.scale)
            else:
                self[field].rescale(self.scale)

def scale(self, other=None):
        if other is None:
            return self.scale_
        elif isinstance(other, numbers.Real):
            self._scale_all(other)
        else:
            raise LenaValueError("Cannot rescale to a non-numeric value")

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    assert isinstance(hist, histogram)
    if make_value is not None:
        assert callable(make_value)
    assert get_coordinate in ("left", "right", "middle")
    assert isinstance(field_names, tuple)
    assert all(isinstance(field, str) for field in field_names)

    if scale is True:
        scale = hist.scale

    graph_bins = []
    for bin_ in hist:
        graph_bin = {}
        for field in field_names:
            if field == "x":
                graph_bin[field] = getattr(bin_, "x")
            else:
                graph_bin[field] = getattr(make_value(bin_), field)
        graph_bins.append(graph_bin)

    graph = graph(bins=graph_bins, scale=scale)
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_.content
    graph = Graph(len(hist.dimensions))
    for bin_ in hist.bins:
        coordinates = [bin_.center if get_coordinate == "left" else
                       bin_.right_edge if get_coordinate == "right" else
                       bin_.center + (bin_.right_edge - bin_.left_edge) / 2]
        if isinstance(field_names, str):
            graph.add(coordinates, make_value(bin_))
        else:
            graph.add(coordinates, [value for value in zip(field_names, make_value(bin_))])
    if scale is True:
        graph.set_scale(hist.scale)
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_
    if get_coordinate == "left":
        get_coordinate = lambda bin_: bin_.left
    elif get_coordinate == "right":
        get_coordinate = lambda bin_: bin_.right
    elif get_coordinate == "middle":
        get_coordinate = lambda bin_: (bin_.right + bin_.left) / 2
    else:
        raise ValueError("Invalid get_coordinate argument")
    graph = graph(scale=scale)
    for bin_ in hist:
        N = len(field_names)
        if N == 2:
            coords = [get_coordinate(bin_)]
            value = make_value(bin_)
            if not isinstance(value, dict):
                value = {"y": value}
            coords.extend(value[field_names[1]])
        elif N == 3:
            coords = [get_coordinate(bin_)]
            value = make_value(bin_)
            if not isinstance(value, dict):
                value = {"y": value}
            coords.extend(value[field_names[1:3]])
        else:
            raise ValueError("Invalid field_names argument")
        graph.add_point(coords, value)
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    graph = Graph(scale=scale)
    for bin in hist:
        if get_coordinate == "left":
            coordinate = bin.left
        elif get_coordinate == "right":
            coordinate = bin.right
        else:
            coordinate = (bin.left + bin.right) / 2
        if make_value:
            value = make_value(bin.value)
        else:
            value = bin.content
        graph.add_point(coordinate, value)
    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    ref = iface
    ref = vtype(iface) if vtype else iface
    noms = getattr(ref, 'names', {})
    ncn = getattr(ref, 'NameCat', None)
    try:
        cprov = getattr(candidate, 'providedBy')
    except AttributeError:
        pass
    else:
        if not cprov.provides('zope.interface.Interface'):
            raise Invalid('It is required that candidates provide `providedBy`, which is an instance of a class implementing the `zope.interface.Interface` interface')
    if not tentative:
        try:
            iclp = getattr(candidate, 'inheritedCachedLiveProvides', None)
            if iclp:
                return iclp[ref]
        except:
            pass
        if ncn:
            try:
                iclp = getattr(candidate, 'inheritedCachedLiveProvides', None)
                if iclp:
                    if ncn in iclp:
                        return iclp[ncn]
            except:
                pass
    if ncn:
        cn = ncn + iface.name
    else:
        cn = iface.name
    einstancecaching = getattr(iface, 'einstancecaching', None)
    if einstancecaching is None:
        einstancecaching = getattr(iface, '__providedBy__', None)
    if not candidate.hasMultipleMethods() and einstancecaching is None:
        raise Invalid("Candidate doesn't have sufficient information to know whether it implements the interface or not")
    try:
        clsp = candidate.classProvides(ref.)
        cnpc = candidate.classProvides(cn)
    except:
        pass
    else:
        try:
            meth, nm = clsp[ref], cnpc[cn]
        except:
            raise Invalid("Candidate is not an instance of a class implementing the interface")
        attrs = dict(inspect.getmembers(meth) if isinstance(meth, type) else meth)
        possattrs = set(attrs.pop('name', []))
        noms = {nm for nm in noms if noms[-1] not in possattrs}
        clas = meth.__objclass__
        missingattrs = frozenset(noms) - possattrs
        if missingattrs:
            raise Invalid("The interface definition contains attributes that are not implemented by the candidate")
        for nm in missingattrs:
            cattr = getattr(clas, nm, None)
            cdescr = getattr(cdescr, nm, None)
            if cattr is None and cdescr is None:
                raise Invalid("The candidate's class or the class's own dict, or the descriptor for the " + nm + " attribute does not have a definition")
            if cdescr is not None and (isinstance(cdescr, type) and not issubclass(cdescr, iface.Attribute) or not isinstance(cdescr, type) and not isinstance(cdescr, iface.Attribute)):
                raise Invalid("The descriptor for the " + nm + " attribute is not an instance of a class extending 'zope.interface.Attribute'")
    try:
        meth, nm = clsp[ref], cnpc[cn]
    except KeyError:
        pass
    elif not isinstance(meth, type) and isinstance(meth, descriptor) and isinstance(meth, boundmethod):
        if meth.__objclass__ is classmethod:
            mth = getattr("method_descriptor", '_method_')
            mcl = mth.__objclass__
            if mcl is classmethod and getattr(mth, 'im_func', None) is getattr(mth, '__func__', None):
                meth = Function((obj, method.__name__), mth)
                newargs, newkw = getattr(meth, '__wrapped__', None), getattr(meth, '__func__', None)
                meth.__wrapped__ = False if newargs is None or newkw is None else newargs
                meth.__func__ = False if newargs is None and newkw is None else newkw
                if mcl is not classmethod:
                    meth.__objclass__ = classmethod
            else:
                meth = ClassMethod((obj, method.__name__), mth)
                coc = getattr(meth, '__objclass__', None)
                coc = coc.__objclass__ if coc is not None and issubclass(coc, ClassMethod) else coc
                meth.__objclass__ = IfaceCMethod(coc, method, classmethod) if coc is classmethod else None
        else:
            if not isinstance(mth, type) and issubclass(mth.__objclass__, IfaceCMethod):
                mcl = getattr(mth, '__objclass__', None)
                if mcl is None or not issubclass(mcl, IfaceCMethod):
                    raise Invalid("The descriptor for the method is a copy of a method of a class implemented by the candidate, but it's wrapped by 'Ifacemethod', and the wrapper class has not been executed.")
            else:
                if iface.__providedBy__ and iface.__providedBy__.dec_object is None:
                    raise Invalid("The providedBy attribute of the interface has not been provided for standard use.")
                raise Invalid("The method is not an instance of a class extending 'zope.interface.Method'")
    elif meth is not None or len(nm) < quitlimit:
        raise Invalid("The candidate's class or the class's own dict does not define a bound method for the interface")
    for nm in ncn:
        attrdescr = iclp[nm]
        if attrdescr is None or not isinstance(attrdescr, desriptor) or not isinstance(attrdescr, attribute):
            raise Invalid("The descriptor for the " + nm + " attribute is not an instance of a class extending 'zope.interface.Attribute'")
        if not meth(candidate):
            raise Invalid("The candidate's class or the class's own dict does not define a getter for the attribute")
    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    provides = getattr(candidate, '__module__') == iface.__module__
    if vtype is None:
        vtype = provides
    if tentative:
        assert provides
    elif not provides:
        return False
    return iface.providesBy(candidate, vtype)

def verifyObject(iface, candidate, tentative=False):
    """Verify that *candidate* might correctly provide *iface*."""
    # Check if the candidate claims to provide the interface using
    # iface.providedBy (unless we're in tentative mode)
    if not isinstance(candidate, iface.providedBy) and not (tentative and isinstance(candidate, iface.providedBy)):
        raise Invalid("%s does not claim to provide %s" % (candidate, iface))

    # Check if the candidate defines all of the required methods
    for required_method in iface.requiredMethods():
        if not hasattr(candidate, required_method):
            raise Invalid("%s: missing required method %s" % (candidate, required_method))

        # Check the signature of the method (as far as possible)
        method_sig = getattr(candidate, required_method).__signature__
        iface_sig = getattr(iface, required_method).__signature__
        if method_sig != iface_sig:
            raise Invalid("%s: incorrect signature for method %s (expected %s, got %s)" % (candidate, required_method, iface_sig, method_sig))

    # Check if the candidate defines all of the required attributes
    for required_attribute in iface.requiredAttribtues():
        if not hasattr(candidate, required_attribute):
            raise Invalid("%s: missing required attribute %s" % (candidate, required_attribute))

    # Return True if all checks passed
    return True

def verifyObject(iface, candidate, tentative=False):
    def check_class_declares_iface():
        if iface.providedBy(candidate.__class__):
            return True
        else:
            raise Invalid("Candidate's class does not declare that it implements interface " + iface.__name__ + ".")

    def check_candidate_declares_iface():
        if iface.getObjectProvides(candidate):
            return True
        else:
            raise Invalid("Candidate does not declare that it provides interface " + iface.__name__ + ".")

    def check_methods_and_attributes_exist():
        for method_name, required_method in iface.getMethodsAndAttributes():
            if method_name in candidate and required_method(candidate) is not None:
                return True
        return False

    def check_methods_have_correct_signature():
        for method_name, required_method in iface.getMethodsAndAttributes():
            if method_name in candidate and required_method.getSignature(candidate) is not None and required_method(candidate).signature() != required_method.getSignature(candidate):
                raise Invalid("Candidate method " + method_name + " does not have the correct signature.")

    return check_class_declares_iface() and check_candidate_declares_iface() and check_methods_and_attributes_exist() and check_methods_have_correct_signature()

def verifyClass(iface, candidate, tentative=False):
    assert isinstance(iface, Interface)
    assert hasattr(candidate, "__class__")
    assert isinstance(candidate.__class__, _Class) or isinstance(candidate.__class__, ABCMeta) or isinstance(candidate.__class__, type)

    if isinstance(candidate.__class__, Interface):
        return False

    for base in getInterfaces(candidate.__class__):
        if base.validate(iface) or (tentative and base.validate(iface, tentative=True)):
            return True

    return False

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    Arguments:
        iface: The interface that the candidate is trying to satisfy.
        candidate: The object that the processor is trying to use.
        tentative (bool): Whether or not the candidate is a tentative match.
    """
    if not isinstance(candidate, iface):
        raise NotImplementedError("The candidate object does not implement the specified interface.")
    if not iface.isinstance(candidate):
        raise ValueError("The candidate object does not match the specified interface.")

    if not tentative:
        if not iface.isinstance(candidate):
            raise ValueError("The candidate object does not match the interface.")

    return candidate

def verifyClass(iface, candidate, tentative=False):
