def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
        # Parse the date/time string into a datetime object
        try:
            dt = datetime.strptime(timestr, self.format)
        except ValueError as e:
            raise ParserError(str(e))

        # If the default is not None and is a datetime object, set the date and
        # time from the default object
        if default is not None and isinstance(default, datetime):
            dt = dt.replace(default.year, default.month, default.day, default.hour, default.minute, default.second, default.microsecond)

        # If the string contains TZ information, replace the tzinfo from the
        # default object
        if tzinfos is not None:
            if isinstance(tzinfos, dict):
                try:
                    dt = dt.replace(tzinfo=tzinfos[dt.tzname()])
                except KeyError as e:
                    raise ParserError(f"Invalid/unknown time zone: {str(e)}")
            elif callable(tzinfos):
                tzinfo = tzinfos(dt.tzname())
                dt = dt.replace(tzinfo=tzinfo)

        # If the string contains the word "now", return the current date and
        # time
        if "now" in timestr:
            dt = datetime.now()

        # If ignoretz is True, convert the datetime object to a naive
        # datetime object
        if ignoretz:
            dt = dt.replace(tzinfo=None)

        # If the kwargs contain "extras", set the extras from the default object
        if "extras" in kwargs:
            kwargs["extras"] = kwargs["extras"].update(default.extras)

        return dt.replace(**kwargs)

