def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    import datetime

    def _parse(spaced=True, fuzzy_with_tokens=False,
               yearfirst=False, dayfirst=False, above=None,
               parserinfo=None, strict=True,
               ignoretz=False, tzinfos=None,
               **kwargs):
        if strict and not self.match(spaced):
            raise ValueError("Could not parse date string")

        if fuzzy_with_tokens:
            return [], datetime.datetime() if default is None else default

        for pad, space in [('0000', ''), ('%Y', ''), ('%m', ''), ('%d', ''), ('%H', ''), ('%M', ''), ('%S', ''), ('%f', ''), ('%z', '')]:
            timestr = timestr.replace(pad, space)

        timestr = timestr.strip()
        tokens = timestr.split(' ')
        count = 0
        year = None
        month = None
        day = None
        hour = None
        minute = None
        second = None
        microsecond = None
        time = None
        tz = None
        for token in tokens:
            if token in ['-', '/'] and count >= 3:
                break
            if count == 0 and len(token) in [4, 2]:
                year = token
            elif count == 1 and len(token) in [2, 1]:
                month = token
            elif count == 2 and len(token) in [2, 1]:
                day = token
            elif count == 3 and len(token) in [1, 2]:
                hour = token
            elif count == 4 and len(token) == 1:
                minute = token
            elif count == 5 and len(token) in [1, 2]:
                second = token
            elif count == 6 and len(token) in [1, 2, 3, 4, 5, 6]:
                microsecond = token
            elif token in ['-', '/', '#', ':', 'T', '@', 'Z']:
                continue
            elif tz is not None:
                tz = tz + token
            elif token.startswith('-') or token.startswith('+'):
                tz = token
            else:
                count += 1

        if default is not None:
            if year is None:
                year = default.strftime('%Y')
            if month is None:
                month = default.strftime('%m')
            if day is None:
                day = default.strftime('%d')
            if hour is None:
                hour = default.strftime('%H')
            if minute is None:
                minute = default.strftime('%M')
            if second is None:
                second = default.strftime('%S')
            if microsecond is None:
                microsecond = default.microsecond
            if tz is None:
                tz = default.tzinfo

        if year is not None and month is not None and day is not None and hour is not None and minute is not None and second is not None and microsecond is not None and tz is not None:
            try:
                year = int(year)
                month = int(month)
                day = int(day)
                hour = int(hour)
                minute = int(minute)
                second = int(second)
                microsecond = int(microsecond)
                if year > 9999 or hour > 23 or minute > 59 or second > 59 or microsecond > 999999:
                    raise ValueError("Invalid date string")
                return datetime.datetime(year, month, day, hour, minute, second, microsecond, tz)
            except ValueError:
                raise ValueError("Invalid date string")
        else:
            raise ValueError("Could not parse date string")

    return _parse(spaced=True, fuzzy_with_tokens=False,
                  yearfirst=False, dayfirst=False, above=None,
                  parserinfo=None, strict=True,
                  ignoretz=False, tzinfos=None)

def fromutc(self, dt):
    if not isinstance(dt, datetime.datetime) or dt.tzinfo is None:
        raise ValueError("Invalid datetime object.")

    # Calculate the offset between the UTCoordinates of the originating and
    # destination timezones
    utcoffset = self.utcoffset(dt) - dt.utcoffset()
    # Invert the sign of the offset if the originating timezone is behind the
    # destination timezone (so that the resulting datetime object is in the
    # destination timezone)
    if utcoffset.total_seconds() < 0:
        utcoffset = -utcoffset

    # Determine whether the datetime is ambiguous and in a "fold" state
    if self.isdst() and self.dst(dt):
        # The current dt is ambiguous, but we don't care because it's in the
        # dst state; just return the original datetime
        return dt
    elif self.isdst() and not self.dst(dt):
        # The current dt is ambiguous and not in the dst state; we need to
        # return the earlier datetime
        return self.localize(dt.replace(tzinfo=None) - utcoffset)
    else:
        # The current dt is not ambiguous; return the original datetime
        return dt

