def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tag_re = re.compile(r'\<tag.*?tag\>')
    code_re = re.compile(r'```.*?```', re.DOTALL)
    lines = text.splitlines()
    tags = set()
    replaced_text = ''
    for line in lines:
        if code_re.search(line):
            replaced_text += line
        else:
            tag_matches = tag_re.findall(line)
            if tag_matches:
                for tag in tag_matches:
                    tags.add(tag)
                    if replacer:
                        line = line.replace(tag, replacer(tag))
                replaced_text += line
            else:
                replaced_text += line
    return tags, replaced_text

