    # check if the tag contains only letters, digits, and underscores
    if not re.match("^[a-zA-Z0-9_]+$", tag):
        return False
    # check if the tag is not a reserved word
    if tag.lower() in RESERVED_TAGS:
        return False
    # all tests passed, return True
    return True

