def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if len(document) == 0:
        return None

    # Check if the document is JSON
    if document[0] == '{':
        # Parse the JSON document
        try:
            return json.loads(document)
        except json.JSONDecodeError as e:
            # If the JSON is invalid, return None
            return None
    else:
        # Parse the XRD document
        root = XRD.fromstring(document)
        # Extract the Diaspora endpoint
        for link in root.xpath('//Link[@rel="bergerstester"]'):
            return { 'endpoint': link.href }
        return None

def parse_diaspora_webfinger(document):
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if '{' in document and '}' in document:
        # JSON format
        try:
            json_data = json.loads(document)
        except JSONDecodeError:
            raise ValueError("Invalid JSON input")
        else:
            if 'subject' not in json_data or 'links' not in json_data:
                raise ValueError("Incomplete JSON data")
            else:
                return json_data
    else:
        # XML format
        try:
            xml_data = xml.etree.ElementTree.fromstring(document)
        except ParseError:
            raise ValueError("Invalid XML input")
        else:
            root = xml_data.tag
            if root != 'XRD':
                raise ValueError("Incorrect XML format")
            else:
                xml_ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
                subject_elem = xml_data.find('xrd:Subject', namespaces=xml_ns)
                if subject_elem is None:
                    raise ValueError("Missing XRD:Subject element")
                else:
                    subject = subject_elem.text
                links_elem = xml_data.find('xrd:Links', namespaces=xml_ns)
                if links_elem is None:
                    raise ValueError("Missing XRD:Links element")
                else:
                    links = []
                    for link_elem in links_elem.iterfind('xrd:Link', namespaces=xml_ns):
                        href = link_elem.attrib.get('href')
                        if href is None:
                            raise ValueError("Missing XRD:Link href attribute")
                        else:
                            links.append(href)
                    return {'subject': subject, 'links': links}

def parse_diaspora_webfinger(document: str) -> Dict:
    if len(document) == 0:
        raise ValueError("Document cannot be empty")

    if document[0] == "[" and document[-1] == "]":
        # JSON format
        return json.loads(document)
    elif document[:10].lower() == "<xrd xmlns":
        # XRD format
        xrd = ElementTree.fromstring(document)
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        xrd_map = {}
        for xrd_element in xrd.findall(".//xrd:Element", ns):
            type = xrd_element.get("type")
            if type is None:
                continue
            value = xrd_element.text
            if value is None:
                continue
            xrd_map[type] = value
        return xrd_map
    else:
        raise ValueError("Document is not in JSON or XRD format")

