def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if dic is None:
        raise ValueError("dic must be a dictionary object")
    if not isinstance(dic, dict):
        raise ValueError("dic must be a dictionary object")
    if keys and not isinstance(keys, str):
        for k in keys:
            if not isinstance(k, str):
                raise ValueError("failed to insert value into dictionyy because one of the keys is not a string")
    if key and not isinstance(key, str):
        raise ValueError("failed to insert value into dictionyy because the key is not a string")
    if not isinstance(val, str):
        raise ValueError("failed to insert value into dictionyy because the value is not a string")

    dic[key] = val
    for subkey in keys:
        if not subkey in dic:
            dic[subkey] = dict()
        dic = dic[subkey]

    return dic

