def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """

        if spec_content is None:
            raise ValueError("Input spec_content is None")

        try:
            data = yaml.load(spec_content, Loader=yaml.Fullloader)
        except yaml.YAMLParseError as e:
            raise IRValidatorException('Invalid spec file: ' + str(e))

        required_fields = ['name', 'commands', 'resources', 'variability']

        try:
            name = data['name']
            commands = data['commands']
            resources = data['resources']
            variability = data['variability']
        except KeyError as e:
            raise IRValidatorException('Mandatory field "' + str(e) + '" is missing in spec file')

        if name is None:
            raise IRValidatorException('Field "name" in spec file is None')

        if commands is None:
            raise IRValidatorException('Field "commands" in spec file is None')

        if resources is None:
            raise IRValidatorException('Field "resources" in spec file is None')

        if variability is None:
            raise IRValidatorException('Field "variability" in spec file is None')

        return data

def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """

    required_fields = cls.MANDATORY_FIELDS + cls.MANDATORY_ATTRIBUTES

    if spec_content is None:
        raise ValueError("No spec content provided")

    try:
        spec_data = spec_content.data
    except:
        raise IRValidatorException("Invalid spec content")

    if not spec_data or not isinstance(spec_data, (dict)):
        raise IRValidatorException("Invalid spec data type")

    for field in required_fields:
        if field not in spec_data:
            raise IRValidatorException("Missing field: %s" % field)

    return spec_data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise ValueError("YAML file path is required")

    with open(yaml_file, "r", encoding="utf-8") as stream:
        try:
            data = yaml.load(stream)
        except YAMLError as exc:
            raise IRValidatorException("Error parsing YAML file") from exc

    missing_fields = cls.get_missing_fields(data)
    if missing_fields:
        raise IRValidatorException(
            "Mandatory fields missing in YAML file: " + ", ".join(missing_fields)
        )

    return data

def _include_groups(self, parser_dict):
        assert isinstance(parser_dict, dict)
        for i in range(len(parser_dict)):
            group = parser_dict[i]
            assert isinstance(group, dict)
            for j in range(len(group)):
                k = group[j]
                assert isinstance(k, str)
                if k not in self.groups:
                    raise KeyError("Group " + k + " not found in spec")
                self.elements.append(self.groups[k])

def _include_groups(self, parser_dict):
    if not parser_dict:
        raise ValueError("The parser_dict argument must be a non-empty dict.")

    includes = parser_dict.get("groups", [])
    if not includes:
        return []

    groups = []
    for include in includes:
        path = include.get("path")
        if not path:
            raise ValueError("The include directive in the spec files must have a valid path.")

        groups.append(self._include_group(path, parser_dict))

    return groups

