def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """

    # Presets from spec or from parent
    self.specs = deepcopy(self.spec) if self.spec else {}
    self.args = {}
    for arg in self.args:
        if "default_value" in self.specs.args[arg]:
            value = self.specs.args[arg]["default_value"]
        elif arg in self.kwargs:
            value = self.kwargs[arg]
        else:
            continue
        self.args[arg] = value

    # Search for inherited values
    if self.inherit:
        parent = self.parent if self.parent else self.__class__.__base__
        if parent != self.__class__:
            self.inherit_args = parent.get_spec_defaults()
            for arg, value in self.inherit_args.items():
                if arg not in self.args:
                    self.args[arg] = value

    # Spec parameters
    self.count = self.args.get("count", 1)
    self.name = self.args.get("name")
    self.desc = self.args.get("desc")
    self.model = self.args.get("model")
    self.prop = self.args.get("prop")

    return self.args

def get_spec_defaults(self):
        spec_defaults = {}
        for arg in self.args:
            if arg.default is not inspect.Parameter.empty:
                spec_defaults[arg.name] = arg.default
            elif arg.type is not inspect.Parameter.empty:
                spec_defaults[arg.name] = arg.type().__name__
            elif inspect.Parameter.empty:
                raise ValueError("Unable to resolve argument's value. No default parameter specified.")
        return spec_defaults

def get_spec_defaults(self):
    self.resolve_arg_values()
    self.resolve_kw_defaults()
    self.resolve_annotation_args()
    self.resolve_tuple_defaults()
    return self.build_defaults_dict()

def get_spec_defaults(self):
    default_value_spec = {}
    for arg, value_spec in self.specs.items():
        # resolve value from spec if it has a default value
        if 'default' in value_spec:
            default_value_spec[arg] = value_spec['default']
        # resolve value from other sources if it doesn't have a spec
        elif 'resolve' in value_spec:
            if value_spec['resolve'] == 'self':
                default_value_spec[arg] = getattr(self, arg)
            elif value_spec['resolve'] == 'default':
                default_value_spec[arg] = None
        else:
            continue  # no matching value found, keep the previous value
    return default_value_spec

