        :return: A flatten dictionary contains the plugin's properties
        """
        plugin_dir = os.path.expanduser(os.path.expandvars(plugin_dir))
        if not os.path.isdir(plugin_dir):
            raise ValueError(f"{plugin_dir} is not a valid directory.")

        spec_path = os.path.join(plugin_dir, "plugin_spec.json")
        if not os.path.isfile(spec_path):
            raise ValueError(f"{spec_path} does not exist.")

        with open(spec_path) as f:
            plugin_spec = json.load(f)

        flatten_dict = {}
        for key, value in plugin_spec.items():
            if isinstance(value, dict):
                for nested_key, nested_value in value.items():
                    flatten_dict[f"{key}.{nested_key}"] = nested_value
            else:
                flatten_dict[key] = value

        return flatten_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = parse_plugin_spec(plugin_dir)
    flatten_dict = {}

    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                flatten_dict[f"{key}.{sub_key}"] = sub_value
