def extend_cli(self, root_subparsers):
    self.cli_options = OrderedDict()

    for cli_option in self.schema.get_cli_options():
        if cli_option.name == '--version':
            continue

        cli_parser = root_subparsers.add_parser(cli_option.name, help=cli_option.help)
        cli_parser.set_defaults(func=self.handle_cli_subcommand)

        for arg in cli_option.args:
            cli_parser.add_argument(arg.name, **arg.to_cli_args())

    return root_subparsers

